32	// ASCII whitespace permitted around the PEM block: the standard C/POSIX set
33	// of horizontal tab, LF, vertical tab, form feed, CR and space (the bytes for
34	// which Python's bytes.isspace() is true within ASCII). Everything else --
35	// including non-ASCII bytes -- is significant content and causes rejection.
36	bool isAsciiSpace(unsigned char c) {
37	    return c == ' ' || (c >= '\t' && c <= '\r');
38	}
