125	// Parses the strict single-block PEM structure:
126	//
127	//   [ASCII ws] -----BEGIN PUBLIC KEY----- LF/CRLF
128	//   (base64 lines; no blank or whitespace-only lines) ...
129	//   -----END PUBLIC KEY----- LF/CRLF
130	//   [ASCII ws]
131	//
132	// Anything else is rejected: non-whitespace outside the block, more than one
133	// block, any other PEM label (private keys, certificates, PKCS#1 RSA public
134	// keys, ...), malformed or truncated base64. Returns the decoded payload
135	// (nominally DER SubjectPublicKeyInfo) on success; structural DER validation
136	// happens in the caller.
137	bool parsePublicPem(const std::vector<unsigned char>& raw,
138	                    std::vector<unsigned char>& payloadOut) {
139	    const size_t n = raw.size();
140	
141	    // Preamble: only ASCII whitespace may precede the block.
142	    size_t pos = 0;
143	    while (pos < n && isAsciiSpace(raw[pos])) {
144	        ++pos;
145	    }
146	    if (pos == n) {
147	        return false;  // empty or whitespace-only file
148	    }
149	
150	    auto takeLine = [&](size_t start,
151	                        std::string_view& line) -> size_t {
152	        size_t end = start;
153	        while (end < n && raw[end] != '\n') {
154	            ++end;
155	        }
156	        line = std::string_view(
157	            reinterpret_cast<const char*>(raw.data() + start), end - start);
158	        return (end < n) ? end + 1 : end;
159	    };
160	
161	    std::string_view line;
162	    pos = takeLine(pos, line);
163	    // Exactly the BEGIN marker, optionally followed by a single CR (CRLF).
164	    if (stripOneCr(line) != kPemBegin) {
165	        return false;
166	    }
167	
168	    std::string base64;
169	    bool sawEnd = false;
170	
171	    while (pos < n) {
172	        pos = takeLine(pos, line);
173	        const std::string_view core = stripOneCr(line);
174	
175	        if (core == kPemEnd) {
176	            sawEnd = true;
177	            break;
178	        }
179	
180	        if (core.empty()) {
181	            return false;  // no blank lines inside the block
182	        }
183	        bool onlySpace = true;
184	        for (char c : core) {
185	            if (!isAsciiSpace(static_cast<unsigned char>(c))) {
186	                onlySpace = false;
187	                break;
188	            }
189	        }
190	        if (onlySpace) {
191	            return false;  // whitespace is allowed only around the block
192	        }
193	
194	        // A payload line must be pure base64. '-' is deliberately not in the
195	        // alphabet, so any other PEM boundary (a second block, a certificate
196	        // or private-key label) fails here rather than being consumed.
197	        for (char c : core) {
198	            if (!isBase64Char(c)) {
199	                return false;
200	            }
201	        }
202	        base64.append(core);
203	    }
204	
205	    if (!sawEnd) {
206	        return false;  // truncated: no END line
207	    }
208	
209	    // Nothing but ASCII whitespace may follow the block through EOF, so a
210	    // second key or any appended text is rejected instead of ignored.
211	    while (pos < n) {
212	        if (!isAsciiSpace(raw[pos])) {
213	            return false;
214	        }
215	        ++pos;
216	    }
217	
218	    return decodeBase64(base64, payloadOut) && !payloadOut.empty();
219	}
220	
221	// Validates that the decoded payload is one complete SubjectPublicKeyInfo DER
222	// structure covering every byte, understood by the crypto library, and in
223	// canonical encoding. Re-encoding the parsed structure must reproduce the
224	// payload byte for byte; that round trip rules out non-DER BER encodings and
225	// other representations OpenSSL might otherwise accept. The bytes hashed for
226	// the fingerprint are therefore the canonical SPKI DER, so PEM line wrapping
227	// and line endings never influence the result.
228	bool extractSpkiDer(const std::vector<unsigned char>& rawBytes,
229	                    std::vector<unsigned char>& derOut) {
230	    std::vector<unsigned char> payload;
231	    if (!parsePublicPem(rawBytes, payload)) {
232	        return false;
233	    }
234	
235	    const unsigned char* p = payload.data();
236	    const std::unique_ptr<EVP_PKEY, decltype(&EVP_PKEY_free)> pkey(
237	        d2i_PUBKEY_ex(nullptr, &p, static_cast<long>(payload.size()), nullptr,
238	                      nullptr),
239	        &EVP_PKEY_free);
240	    if (!pkey) {
241	        return false;
242	    }
243	    if (p - payload.data() != static_cast<ptrdiff_t>(payload.size())) {
244	        return false;  // trailing bytes after the SPKI structure
245	    }
246	
247	    const int encLen = i2d_PUBKEY(pkey.get(), nullptr);
248	    if (encLen <= 0 ||
249	        static_cast<size_t>(encLen) != payload.size()) {
250	        return false;
251	    }
252	    std::vector<unsigned char> reencoded(static_cast<size_t>(encLen));
253	    unsigned char* q = reencoded.data();
254	    if (i2d_PUBKEY(pkey.get(), &q) != encLen || reencoded != payload) {
255	        return false;  // non-canonical DER
256	    }
257	
258	    derOut = std::move(payload);
259	    return true;
260	}
261	
262	// Reads the whole regular file into memory. Parsing a PEM public key
263	// fundamentally requires all of its bytes; public keys are small, so this
264	// does not stream like digest/verify-digest. On failure prints a reason
265	// (including the given path) to stderr and returns false.
266	bool readFileAll(const char* pathArg, std::vector<unsigned char>& out) {
267	    namespace fs = std::filesystem;
268	    const fs::path path(pathArg);
269	
270	    std::error_code ec;
271	    if (!fs::is_regular_file(path, ec)) {
272	        if (ec) {
273	            std::cerr << "sealmark: cannot access '" << pathArg << "': "
274	                      << ec.message() << '\n';
275	        } else {
276	            std::cerr << "sealmark: '" << pathArg
277	                      << "' is not a regular file\n";
278	        }
279	        return false;
280	    }
281	
282	    errno = 0;
283	    std::ifstream in(path, std::ios::binary);
284	    if (!in) {
285	        const int err = errno;
286	        std::cerr << "sealmark: cannot open '" << pathArg << "': "
287	                  << (err != 0 ? std::strerror(err) : "open failed") << '\n';
288	        return false;
289	    }
290	
291	    std::vector<unsigned char> bytes;
292	    std::vector<char> buffer(64 * 1024);
293	    while (in) {
294	        in.read(buffer.data(), static_cast<std::streamsize>(buffer.size()));
295	        const std::streamsize got = in.gcount();
296	        if (got > 0) {
297	            bytes.insert(bytes.end(), buffer.data(), buffer.data() + got);
298	        }
299	    }
300	    if (in.bad()) {
301	        std::cerr << "sealmark: failed to read '" << pathArg << "'\n";
302	        return false;
303	    }
304	    out = std::move(bytes);
305	    return true;
306	}
307	
308	int keyIdFile(const char* pathArg) {
309	    std::vector<unsigned char> raw;
310	    if (!readFileAll(pathArg, raw)) {
311	        return 1;
312	    }
313	
314	    std::vector<unsigned char> spkiDer;
315	    if (!extractSpkiDer(raw, spkiDer)) {
316	        std::cerr << "sealmark: '" << pathArg
317	                  << "' does not contain a single valid PEM-encoded "
318	                     "SubjectPublicKeyInfo public key (PUBLIC KEY)\n";
319	        return 1;
320	    }
321	
322	    unsigned char hash[kSha256Size];
323	    unsigned int hashLen = 0;
324	    if (EVP_Digest(spkiDer.data(), spkiDer.size(), hash, &hashLen,
325	                   EVP_sha256(), nullptr) != 1 ||
326	        hashLen != kSha256Size) {
327	        std::cerr << "sealmark: SHA-256 computation failed for '" << pathArg
328	                  << "'\n";
329	        return 1;
330	    }
331	
332	    static constexpr char kHex[] = "0123456789abcdef";
333	    std::cout << kSpkiFingerprintPrefix;
334	    for (unsigned char byte : hash) {
335	        std::cout << kHex[byte >> 4] << kHex[byte & 0x0f];
336	    }
337	    std::cout << '\n';
338	    return 0;
339	}
340	
341	// Streams the file's complete raw bytes through SHA-256 using fixed-size
342	// buffers, so memory use stays constant regardless of file size. On success
343	// fills hashOut with exactly kSha256Size bytes and returns true; on failure
344	// prints a reason (including pathArg) to stderr and returns false.
345	bool hashFile(const char* pathArg, unsigned char hashOut[kSha256Size]) {
346	    namespace fs = std::filesystem;
347	    const fs::path path(pathArg);
348	
349	    std::error_code ec;
350	    if (!fs::is_regular_file(path, ec)) {
351	        if (ec) {
352	            std::cerr << "sealmark: cannot access '" << pathArg << "': " << ec.message() << '\n';
353	        } else {
354	            std::cerr << "sealmark: '" << pathArg << "' is not a regular file\n";
355	        }
356	        return false;
357	    }
358	
359	    errno = 0;
360	    std::ifstream in(path, std::ios::binary);
361	    if (!in) {
362	        const int err = errno;
363	        std::cerr << "sealmark: cannot open '" << pathArg << "': "
364	                  << (err != 0 ? std::strerror(err) : "open failed") << '\n';
365	        return false;
366	    }
367	
368	    const std::unique_ptr<EVP_MD_CTX, decltype(&EVP_MD_CTX_free)> ctx(EVP_MD_CTX_new(),
369	                                                                      &EVP_MD_CTX_free);
370	    if (!ctx || EVP_DigestInit_ex(ctx.get(), EVP_sha256(), nullptr) != 1) {
371	        std::cerr << "sealmark: SHA-256 initialization failed for '" << pathArg << "'\n";
372	        return false;
373	    }
374	
375	    // Stream the file in fixed-size chunks so memory use stays constant
376	    // regardless of file size.
377	    std::vector<char> buffer(64 * 1024);
378	    while (in) {
379	        in.read(buffer.data(), static_cast<std::streamsize>(buffer.size()));
380	        const std::streamsize got = in.gcount();
381	        if (got > 0 &&
382	            EVP_DigestUpdate(ctx.get(), buffer.data(), static_cast<size_t>(got)) != 1) {
383	            std::cerr << "sealmark: SHA-256 computation failed for '" << pathArg << "'\n";
384	            return false;
385	        }
386	    }
387	    if (in.bad()) {
388	        std::cerr << "sealmark: failed to read '" << pathArg << "'\n";
389	        return false;
390	    }
391	
392	    unsigned int hashLen = 0;
393	    if (EVP_DigestFinal_ex(ctx.get(), hashOut, &hashLen) != 1 ||
394	        hashLen != kSha256Size) {
395	        std::cerr << "sealmark: SHA-256 computation failed for '" << pathArg << "'\n";
396	        return false;
397	    }
398	    return true;
399	}
400	
401	int digestFile(const char* pathArg) {
402	    unsigned char hash[kSha256Size];
403	    if (!hashFile(pathArg, hash)) {
404	        return 1;
405	    }
406	
407	    static constexpr char kHex[] = "0123456789abcdef";
408	    std::cout << "sha256:";
409	    for (unsigned char byte : hash) {
410	        std::cout << kHex[byte >> 4] << kHex[byte & 0x0f];
411	    }
412	    std::cout << '\n';
413	    return 0;
414	}
415	
416	// Accepts only "sha256:" followed by exactly 64 lowercase hexadecimal
417	// characters: no missing prefix, no uppercase, no other algorithm names,
418	// no surrounding whitespace or trailing content.
419	bool isValidExpectedDigest(std::string_view digest) {
420	    if (digest.size() != kDigestPrefix.size() + kDigestHexLen) {
421	        return false;
422	    }
423	    if (digest.substr(0, kDigestPrefix.size()) != kDigestPrefix) {
424	        return false;
425	    }
426	    for (size_t i = kDigestPrefix.size(); i < digest.size(); ++i) {
427	        const char c = digest[i];
428	        const bool isHex =
429	            (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f');
430	        if (!isHex) {
431	            return false;
432	        }
433	    }
434	    return true;
435	}
436	
437	int verifyDigestFile(const char* pathArg, std::string_view expected) {
438	    unsigned char hash[kSha256Size];
439	    if (!hashFile(pathArg, hash)) {
440	        return 1;
441	    }
442	
443	    static constexpr char kHex[] = "0123456789abcdef";
444	    char actual[kDigestPrefix.size() + kDigestHexLen];
445	    std::memcpy(actual, kDigestPrefix.data(), kDigestPrefix.size());
446	    for (size_t i = 0; i < kSha256Size; ++i) {
447	        actual[kDigestPrefix.size() + 2 * i] = kHex[hash[i] >> 4];
448	        actual[kDigestPrefix.size() + 2 * i + 1] = kHex[hash[i] & 0x0f];
449	    }
450	
451	    if (std::string_view(actual, sizeof(actual)) == expected) {
452	        std::cout << "match\n";
453	        return 0;
454	    }
455	    std::cout << "mismatch\n";
456	    return 3;
457	}
458	
459	}  // namespace
460	
461	int main(int argc, char* argv[]) {
462	    if (argc == 2 && std::string_view(argv[1]) == "--version") {
463	        std::cout << "sealmark 0.1.0\n";
464	        return 0;
465	    }
466	    if (argc == 3 && std::string_view(argv[1]) == "digest") {
467	        if (argv[2][0] == '\0') {
468	            return printUsage();
469	        }
470	        return digestFile(argv[2]);
471	    }
472	    if (argc == 3 && std::string_view(argv[1]) == "key-id") {
473	        if (argv[2][0] == '\0') {
474	            return printUsage();
475	        }
476	        return keyIdFile(argv[2]);
477	    }
478	    if (argc == 4 && std::string_view(argv[1]) == "verify-digest") {
479	        // Validate every argument before touching the file so that a bad
480	        // path and a malformed digest together still report a usage error.
481	        if (argv[2][0] == '\0' || !isValidExpectedDigest(argv[3])) {
482	            return printUsage();
483	        }
484	        return verifyDigestFile(argv[2], argv[3]);
485	    }
486	    return printUsage();
487	}
